<script type="module">
import * as THREE from 'three';

/* ---------- deterministic noise ---------- */
function hash(x,y){const s=Math.sin(x*127.1+y*311.7)*43758.5453;return s-Math.floor(s);}
function vnoise(x,y){
  const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi;
  const u=xf*xf*(3-2*xf),v=yf*yf*(3-2*yf);
  const a=hash(xi,yi),b=hash(xi+1,yi),c=hash(xi,yi+1),d=hash(xi+1,yi+1);
  return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v;
}
function fbm(x,y){let f=0,amp=.5,fr=1;for(let i=0;i<4;i++){f+=amp*vnoise(x*fr,y*fr);fr*=2;amp*=.5;}return f;}
function smoothstep(a,b,x){x=Math.min(1,Math.max(0,(x-a)/(b-a)));return x*x*(3-2*x);}
function rand(a,b){return a+Math.random()*(b-a);}
function pick(a){return a[Math.floor(Math.random()*a.length)];}

/* ---------- renderer / scene / camera ---------- */
const canvas=document.getElementById('scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.05;
renderer.outputColorSpace=THREE.SRGBColorSpace;

const scene=new THREE.Scene();
scene.background=new THREE.Color(0x0a141b);
scene.fog=new THREE.FogExp2(0x0a141b,0.011);

const camera=new THREE.PerspectiveCamera(46,innerWidth/innerHeight,0.1,400);
camera.position.set(0,16,34);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xbfe0ff,0x2a2016,0.55));
const sun=new THREE.DirectionalLight(0xfff0d6,1.7);
sun.position.set(26,34,18);
sun.castShadow=true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.near=1; sun.shadow.camera.far=120;
sun.shadow.camera.left=-34; sun.shadow.camera.right=34;
sun.shadow.camera.top=34; sun.shadow.camera.bottom=-34;
sun.shadow.bias=-0.0004; sun.shadow.normalBias=0.02;
scene.add(sun);
const fill=new THREE.DirectionalLight(0x8fb4ff,0.35); fill.position.set(-20,14,-16); scene.add(fill);

/* ---------- water ---------- */
const waterGeo=new THREE.PlaneGeometry(240,240,1,1);
const waterMat=new THREE.MeshStandardMaterial({color:0x0e3a4a,roughness:0.12,metalness:0.55,
  transparent:true,opacity:0.92,emissive:0x06222c,emissiveIntensity:0.4});
const water=new THREE.Mesh(waterGeo,waterMat);
water.rotation.x=-Math.PI/2; water.position.y=-0.05; water.receiveShadow=true;
scene.add(water);

/* ---------- island terrain ---------- */
function makeIsland({radius=6,peak=3.2,rough=0.55,seed=0,base=0x8a6a3a,high=0xd8b06a,
  rim=0x5a4326,rimStart=0.82,rimEnd=0.985,flat=0.12}){
  const geo=new THREE.CylinderGeometry(radius,radius*1.12,peak,72,14);
  const pos=geo.attributes.position;
  const v=new THREE.Vector3();
  for(let i=0;i<pos.count;i++){
    v.fromBufferAttribute(pos,i);
    const r=Math.hypot(v.x,v.z);
    const hN=v.y/peak+0.5;
    const n=fbm(v.x*0.55+seed,v.z*0.55+seed);
    let y=v.y+(n-0.5)*rough*peak;
    const rimF=smoothstep(rimStart,rimEnd,r/radius);
    y-=rimF*peak*0.95;
    const flatF=smoothstep(0.15,0.55,hN);
    y+=(1-flatF)*flat*peak*(n-0.5);
    pos.setY(i,y);
  }
  geo.computeVertexNormals();
  const colors=new Float32Array(pos.count*3);
  const cBase=new THREE.Color(base),cHigh=new THREE.Color(high),cRim=new THREE.Color(rim),tmp=new THREE.Color();
  for(let i=0;i<pos.count;i++){
    v.fromBufferAttribute(pos,i);
    const r=Math.hypot(v.x,v.z);
    const hN=v.y/peak+0.5;
    const rimF=smoothstep(rimStart,rimEnd,r/radius);
    tmp.copy(cBase).lerp(cHigh,smoothstep(0.2,0.95,hN));
    tmp.lerp(cRim,rimF);
    const j=(hash(i,seed)-0.5)*0.06;
    colors[i*3]=tmp.r+j; colors[i*3+1]=tmp.g+j; colors[i*3+2]=tmp.b+j;
  }
  geo.setAttribute('color',new THREE.BufferAttribute(colors,3));
  const mat=new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.95,metalness:0.0,flatShading:true});
  const mesh=new THREE.Mesh(geo,mat);
  mesh.castShadow=true; mesh.receiveShadow=true;
  return mesh;
}

/* ---------- helpers ---------- */
function surfaceY(island,x,z){
  const r=Math.hypot(x,z),R=island.userData.radius;
  const peak=island.userData.peak;
  const rimF=smoothstep(island.userData.rimStart,island.userData.rimEnd,r/R);
  const n=fbm(x*0.55+island.userData.seed,z*0.55+island.userData.seed);
  let y=peak*(1-rimF*0.95)+(n-0.5)*island.userData.rough*peak;
  return y;
}
function placeOnIsland(island,obj,radMin,radMax){
  const R=island.userData.radius;
  const a=Math.random()*Math.PI*2;
  const r=rand(radMin,radMax)*R;
  const x=Math.cos(a)*r,z=Math.sin(a)*r;
  obj.position.set(x,surfaceY(island,x,z),z);
  obj.rotation.y=Math.random()*Math.PI*2;
  return obj;
}
function makeIslandGroup(cfg){
  const g=new THREE.Group();
  const mesh=makeIsland(cfg);
  mesh.userData={radius:cfg.radius,peak:cfg.peak,rough:cfg.rough,seed:cfg.seed,
    rimStart:cfg.rimStart,rimEnd:cfg.rimEnd};
  g.add(mesh);
  g.userData.island=mesh;
  return g;
}

/* ---------- vegetation ---------- */
function makeCactus(){
  const g=new THREE.Group();
  const m=new THREE.MeshStandardMaterial({color:0x4f8f4a,roughness:0.85,flatShading:true});
  const body=new THREE.Mesh(new THREE.CylinderGeometry(0.28,0.34,1.7,8),m);
  body.position.y=0.85; body.castShadow=true; g.add(body);
  const armGeo=new THREE.CylinderGeometry(0.16,0.18,0.9,7);
  const arm1=new THREE.Mesh(armGeo,m); arm1.position.set(0.42,1.0,0); arm1.rotation.z=-0.9; arm1.castShadow=true; g.add(arm1);
  const arm2=new THREE.Mesh(armGeo,m); arm2.position.set(-0.4,0.85,0.1); arm2.rotation.z=0.95; arm2.castShadow=true; g.add(arm2);
  const cap=new THREE.Mesh(new THREE.SphereGeometry(0.3,8,6),m); cap.position.y=1.7; cap.castShadow=true; g.add(cap);
  return g;
}
function makePalm(){
  const g=new THREE.Group();
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(0.14,0.22,2.4,7),
    new THREE.MeshStandardMaterial({color:0x8a6a3a,roughness:0.9,flatShading:true}));
  trunk.position.y=1.2; trunk.castShadow=true; g.add(trunk);
  const leafMat=new THREE.MeshStandardMaterial({color:0x3f8f4a,roughness:0.8,flatShading:true,side:THREE.DoubleSide});
  for(let i=0;i<6;i++){
    const leaf=new THREE.Mesh(new THREE.ConeGeometry(0.16,1.6,4),leafMat);
    const a=i/6*Math.PI*2;
    leaf.position.set(Math.cos(a)*0.5,2.4,Math.sin(a)*0.5);
    leaf.rotation.set(Math.sin(a)*0.9,0,-Math.cos(a)*0.9);
    leaf.castShadow=true; g.add(leaf);
  }
  return g;
}
function makeRock(){
  const g=new THREE.Group();
  const m=new THREE.MeshStandardMaterial({color:0x9a8a72,roughness:1,flatShading:true});
  const r=new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.3,0.7),0),m);
  r.scale.set(1,rand(0.6,0.9),1); r.castShadow=true; r.receiveShadow=true; g.add(r);
  return g;
}
function makePine(){
  const g=new THREE.Group();
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(0.16,0.24,1.0,7),
    new THREE.MeshStandardMaterial({color:0x5a3a22,roughness:0.9,flatShading:true}));
  trunk.position.y=0.5; trunk.castShadow=true; g.add(trunk);
  const leaf=new THREE.MeshStandardMaterial({color:0x2f7a44,roughness:0.85,flatShading:true});
  const tiers=[[1.1,1.4,1.0],[0.85,1.1,1.7],[0.6,0.9,2.3]];
  tiers.forEach(([rad,h,y])=>{
    const c=new THREE.Mesh(new THREE.ConeGeometry(rad,h,7),leaf);
    c.position.y=y; c.castShadow=true; g.add(c);
  });
  return g;
}
function makeFern(){
  const g=new THREE.Group();
  const m=new THREE.MeshStandardMaterial({color:0x4f9a4a,roughness:0.8,flatShading:true,side:THREE.DoubleSide});
  for(let i=0;i<5;i++){
    const leaf=new THREE.Mesh(new THREE.ConeGeometry(0.12,0.7,4),m);
    const a=i/5*Math.PI*2;
    leaf.position.set(Math.cos(a)*0.18,0.3,Math.sin(a)*0.18);
    leaf.rotation.set(Math.sin(a)*0.7,0,-Math.cos(a)*0.7);
    leaf.castShadow=true; g.add(leaf);
  }
  return g;
}
function makeSnowPine(){
  const g=new THREE.Group();
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(0.14,0.2,0.9,7),
    new THREE.MeshStandardMaterial({color:0x4a3320,roughness:0.9,flatShading:true}));
  trunk.position.y=0.45; trunk.castShadow=true; g.add(trunk);
  const leaf=new THREE.MeshStandardMaterial({color:0x2f6a4a,roughness:0.85,flatShading:true});
  const snow=new THREE.MeshStandardMaterial({color:0xf2f7ff,roughness:0.6,flatShading:true});
  const tiers=[[1.0,1.3,0.9],[0.75,1.0,1.5],[0.5,0.8,2.0]];
  tiers.forEach(([rad,h,y])=>{
    const c=new THREE.Mesh(new THREE.ConeGeometry(rad,h,7),leaf); c.position.y=y; c.castShadow=true; g.add(c);
    const cap=new THREE.Mesh(new THREE.ConeGeometry(rad*0.55,0.28,7),snow); cap.position.y=y+h*0.42; cap.castShadow=true; g.add(cap);
  });
  return g;
}
function makeIce(){
  const g=new THREE.Group();
  const m=new THREE.MeshStandardMaterial({color:0xbfe6ff,roughness:0.25,metalness:0.1,
    transparent:true,opacity:0.85,flatShading:true});
  const r=new THREE.Mesh(new THREE.IcosahedronGeometry(rand(0.3,0.6),0),m);
  r.scale.set(1,rand(1.2,1.8),1); r.castShadow=true; g.add(r);
  return g;
}

/* ---------- animals ---------- */
function makeLizard(){
  const g=new THREE.Group();
  const m=new THREE.MeshStandardMaterial({color:0x6fae5a,roughness:0.7,flatShading:true});
  const body=new THREE.Mesh(new THREE.CapsuleGeometry(0.22,0.7,4,8),m);
  body.rotation.z=Math.PI/2; body.position.y=0.28; body.castShadow=true; g.add(body);
  const head=new THREE.Mesh(new THREE.ConeGeometry(0.2,0.4,6),m);
  head.rotation.z=-Math.PI/2; head.position.set(0.6,0.3,0); head.castShadow=true; g.add(head);
  const tail=new THREE.Mesh(new THREE.ConeGeometry(0.16,0.7,6),m);
  tail.rotation.z=Math.PI/2; tail.position.set(-0.6,0.28,0); tail.castShadow=true; g.add(tail);
  const legGeo=new THREE.CylinderGeometry(0.06,0.06,0.28,5);
  [[0.3,0.18],[0.3,-0.18],[-0.3,0.18],[-0.3,-0.18]].forEach(([x,z])=>{
    const l=new THREE.Mesh(legGeo,m); l.position.set(x,0.14,z); l.castShadow=true; g.add(l);
  });
  return g;
}
function makeDeer(){
  const g=new THREE.Group();
  const body=new THREE.MeshStandardMaterial({color:0x9a6a3a,roughness:0.8,flatShading:true});
  const dark=new THREE.MeshStandardMaterial({color:0x5a3a22,roughness:0.8,flatShading:true});
  const torso=new THREE.Mesh(new THREE.CapsuleGeometry(0.32,0.9,4,8),body);
  torso.rotation.z=Math.PI/2; torso.position.y=0.7; torso.castShadow=true; g.add(torso);
  const neck=new THREE.Mesh(new THREE.CylinderGeometry(0.16,0.2,0.7,7),body);
  neck.position.set(0.55,1.0,0); neck.rotation.z=-0.5; neck.castShadow=true; g.add(neck);
  const head=new THREE.Mesh(new THREE.ConeGeometry(0.22,0.5,6),body);
  head.rotation.z=-Math.PI/2-0.3; head.position.set(0.85,1.25,0); head.castShadow=true; g.add(head);
  const antGeo=new THREE.CylinderGeometry(0.03,0.03,0.4,5);
  [[0.15],[ -0.15]].forEach(([z])=>{
    const a=new THREE.Mesh(antGeo,dark); a.position.set(0.8,1.55,z); a.rotation.z=0.3; a.castShadow=true; g.add(a);
  });
  const legGeo=new THREE.CylinderGeometry(0.07,0.07,0.7,6);
  [[0.4,0.2],[0.4,-0.2],[-0.4,0.2],[-0.4,-0.2]].forEach(([x,z])=>{
    const l=new THREE.Mesh(legGeo,body); l.position.set(x,0.35,z); l.castShadow=true; g.add(l);
  });
  const tail=new THREE.Mesh(new THREE.SphereGeometry(0.1,6,5),dark);
  tail.position.set(-0.6,0.75,0); tail.castShadow=true; g.add(tail);
  return g;
}
function makePenguin(){
  const g=new THREE.Group();
  const black=new THREE.MeshStandardMaterial({color:0x1a1a22,roughness:0.6,flatShading:true});
  const white=new THREE.MeshStandardMaterial({color:0xf4f6ff,roughness:0.6,flatShading:true});
  const orange=new THREE.MeshStandardMaterial({color:0xf0a020,roughness:0.6,flatShading:true});
  const body=new THREE.Mesh(new THREE.CapsuleGeometry(0.34,0.5,4,8),black);
  body.position.y=0.6; body.castShadow=true; g.add(body);
  const belly=new THREE.Mesh(new THREE.CapsuleGeometry(0.28,0.4,4,8),white);
  belly.position.set(0,0.58,0.12); belly.castShadow=true; g.add(belly);
  const head=new THREE.Mesh(new THREE.SphereGeometry(0.26,10,8),black);
  head.position.y=1.15; head.castShadow=true; g.add(head);
  const beak=new THREE.Mesh(new THREE.ConeGeometry(0.09,0.22,5),orange);
  beak.rotation.z=-Math.PI/2; beak.position.set(0.28,1.12,0); beak.castShadow=true; g.add(beak);
  const wingGeo=new THREE.CapsuleGeometry(0.09,0.3,3,6);
  [[0.32],[-0.32]].forEach(([x])=>{
    const w=new THREE.Mesh(wingGeo,black); w.position.set(x,0.6,0); w.rotation.z=x>0?-0.4:0.4; w.castShadow=true; g.add(w);
  });
  const footGeo=new THREE.ConeGeometry(0.1,0.16,5);
  [[0.14],[-0.14]].forEach(([x])=>{
    const f=new THREE.Mesh(footGeo,orange); f.rotation.z=Math.PI/2; f.position.set(x,0.08,0.12); f.castShadow=true; g.add(f);
  });
  return g;
}

/* ---------- build islands ---------- */
const world=new THREE.Group(); scene.add(world);
const animals=[];

// DESERT
const desert=makeIslandGroup({radius:6,peak:3.0,rough:0.5,seed:11,
  base:0xc98a3e,high:0xe8c07a,rim:0x7a5a2e,rimStart:0.8,rimEnd:0.985,flat:0.1});
desert.position.set(-13,0,-4); world.add(desert);
for(let i=0;i<4;i++){const c=makeCactus();placeOnIsland(desert.userData.island,c,0.2,0.6);desert.add(c);}
for(let i=0;i<3;i++){const p=makePalm();placeOnIsland(desert.userData.island,p,0.3,0.65);desert.add(p);}
for(let i=0;i<6;i++){const r=makeRock();placeOnIsland(desert.userData.island,r,0.15,0.7);desert.add(r);}
const lizard=makeLizard(); placeOnIsland(desert.userData.island,lizard,0.3,0.5);
lizard.userData={baseY:0,phase:Math.random()*6}; desert.add(lizard); animals.push(lizard);

// FOREST
const forest=makeIslandGroup({radius:6.5,peak:3.6,rough:0.6,seed:42,
  base:0x3f7a3a,high:0x6aa84a,rim:0x2a4a24,rimStart:0.8,rimEnd:0.985,flat:0.12});
forest.position.set(13,0,3); world.add(forest);
for(let i=0;i<7;i++){const p=makePine();placeOnIsland(forest.userData.island,p,0.2,0.7);forest.add(p);}
for(let i=0;i<5;i++){const f=makeFern();placeOnIsland(forest.userData.island,f,0.2,0.75);forest.add(f);}
for(let i=0;i<4;i++){const r=makeRock();placeOnIsland(forest.userData.island,r,0.2,0.7);forest.add(r);}
const deer=makeDeer(); placeOnIsland(forest.userData.island,deer,0.3,0.55);
deer.userData={baseY:0,phase:Math.random()*6}; forest.add(deer); animals.push(deer);

// SNOW
const snow=makeIslandGroup({radius:6,peak:3.2,rough:0.45,seed:77,
  base:0xdfe8f2,high:0xffffff,rim:0x9fb4c8,rimStart:0.8,rimEnd:0.985,flat:0.1});
snow.position.set(0,0,13); world.add(snow);
for(let i=0;i<6;i++){const p=makeSnowPine();placeOnIsland(snow.userData.island,p,0.2,0.7);snow.add(p);}
for(let i=0;i<5;i++){const ic=makeIce();placeOnIsland(snow.userData.island,ic,0.2,0.75);snow.add(ic);}
const penguin=makePenguin(); placeOnIsland(snow.userData.island,penguin,0.3,0.5);
penguin.userData={baseY:0,phase:Math.random()*6}; snow.add(penguin); animals.push(penguin);

/* ---------- ambient particles ---------- */
function makeParticles(count,color,size,spread,baseY){
  const geo=new THREE.BufferGeometry();
  const arr=new Float32Array(count*3);
  for(let i=0;i<count;i++){
    arr[i*3]=rand(-spread,spread);
    arr[i*3+1]=rand(baseY,baseY+14);
    arr[i*3+2]=rand(-spread,spread);
  }
  geo.setAttribute('position',new THREE.BufferAttribute(arr,3));
  const mat=new THREE.PointsMaterial({color,size,transparent:true,opacity:0.7,
    depthWrite:false,sizeAttenuation:true});
  const pts=new THREE.Points(geo,mat); scene.add(pts);
  return pts;
}
const snowPts=makeParticles(260,0xffffff,0.14,26,0);
const dustPts=makeParticles(120,0xe8c07a,0.1,26,0);

/* ---------- orbit controls (inline, no addons) ---------- */
let theta=0.6, phi=1.05, radius=34, target=new THREE.Vector3(0,2,0);
let dragging=false, px=0, py=0;
canvas.addEventListener('pointerdown',e=>{dragging=true;px=e.clientX;py=e.clientY;});
addEventListener('pointerup',()=>dragging=false);
addEventListener('pointermove',e=>{
  if(!dragging)return;
  theta-=(e.clientX-px)*0.005;
  phi-=(e.clientY-py)*0.005;
  phi=Math.max(0.25,Math.min(1.45,phi));
  px=e.clientX;py=e.clientY;
});
canvas.addEventListener('wheel',e=>{
  e.preventDefault();
  radius=Math.max(14,Math.min(70,radius+e.deltaY*0.02));
},{passive:false});

/* ---------- animation ---------- */
const clock=new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const t=clock.getElapsedTime();
  if(!dragging) theta+=0.0016;
  camera.position.set(
    target.x+radius*Math.sin(phi)*Math.sin(theta),
    target.y+radius*Math.cos(phi),
    target.z+radius*Math.sin(phi)*Math.cos(theta)
  );
  camera.lookAt(target);

  // gentle island bob
  world.children.forEach((g,i)=>{g.position.y=Math.sin(t*0.5+i*2)*0.12;});

  // animals idle
  animals.forEach(a=>{
    a.position.y=a.userData.baseY+Math.sin(t*2+a.userData.phase)*0.05;
    a.rotation.y+=0.0008;
  });

  // particles drift
  const sp=snowPts.geometry.attributes.position;
  for(let i=0;i<sp.count;i++){
    let y=sp.getY(i)-0.02; if(y<0)y=14; sp.setY(i,y);
    sp.setX(i,sp.getX(i)+Math.sin(t+i)*0.002);
  }
  sp.needsUpdate=true;
  const dp=dustPts.geometry.attributes.position;
  for(let i=0;i<dp.count;i++){
    let y=dp.getY(i)+0.015; if(y>14)y=0; dp.setY(i,y);
  }
  dp.needsUpdate=true;

  // water shimmer
  waterMat.emissiveIntensity=0.35+Math.sin(t*1.2)*0.12;

  renderer.render(scene,camera);
}
animate();

addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

/* ---------- expose for inspection ---------- */
window.SCENE=scene;
window.CAMERA=camera;
window.RENDERER=renderer;
