      x.fillStyle=band; x.globalAlpha=Math.random()*0.5+0.2;
      x.fillRect(0,y,256,h);
    }
    x.globalAlpha=1;
  }
  for(let i=0;i<900;i++){
    const px=Math.random()*256, py=Math.random()*128, r=Math.random()*2+0.4;
