  { name:'Earth',   color:0x4a90d9, base:'#2f6fb0', band:'#3f86c9', speckle:'#7fd0a0',
    radius:1.8, orbit:34, speed:1.00, spin:0.03, tilt:0.41, desc:'1.00 AU · 365 d',
    moon:{ name:'Moon', color:0xb8b8b8, base:'#9a9a9a', band:'#7d7d7d', speckle:'#cfcfcf',
           radius:0.5, orbit:4.2, speed:3.4, spin:0.02, desc:'384,400 km · 27 d' } },
  { name:'Mars',    color:0xc1502e, base:'#b5432a', band:'#8f3320', speckle:'#e08a5a',
    radius:1.4, orbit:46, speed:0.80, spin:0.028, tilt:0.44, desc:'1.52 AU · 687 d' }
];

const orbitLines = [];
const pickables = [];
const labelSprites = [];
const planetGroups = [];

function makeLabel(text, colorHex){
  const c = makeCanvas(256,64), x = c.getContext('2d');
  x.font = '600 30px "Space Grotesk", sans-serif';
  x.textAlign='center'; x.textBaseline='middle';
  x.shadowColor='rgba(0,0,0,0.9)'; x.shadowBlur=8;
  x.fillStyle='#'+colorHex.toString(16).padStart(6,'0');
  x.fillText(text, 128, 32);
  const t = new THREE.CanvasTexture(c); t.colorSpace=THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map:t, transparent:true, depthWrite:false }));
  sp.scale.set(9, 2.25, 1);
  return sp;
}

function makeOrbit(radius, colorHex){
  const pts=[];
  for(let i=0;i<=128;i++){
    const a=i/128*Math.PI*2;
    pts.push(new THREE.Vector3(Math.cos(a)*radius, 0, Math.sin(a)*radius));
  }
  const g=new THREE.BufferGeometry().setFromPoints(pts);
  const m=new THREE.LineBasicMaterial({ color:colorHex, transparent:true, opacity:0.28 });
