  holder.add(mesh);

  // subtle rim glow
  const rim = new THREE.Sprite(new THREE.SpriteMaterial({
    map:glowTexture('rgba(255,255,255,0.35)','rgba(0,0,0,0)'),
    color:p.color, transparent:true, blending:THREE.AdditiveBlending, depthWrite:false, opacity:0.5
  }));
  rim.scale.set(p.radius*4.2, p.radius*4.2, 1);
  holder.add(rim);

