  );
  proxy.userData = { name:p.name, color:p.color, desc:p.desc, mesh, holder };
  holder.add(proxy);
  pickables.push(proxy);

  planetGroups.push({ pivot, holder, mesh, moonPivot, moonMesh, speed:p.speed, spin:p.spin, moonSpeed:p.moon?p.moon.speed:0 });
});

