const legendList = document.getElementById('legend-list');
const legendData = [
  { name:'Sun', color:0xffb347, meta:'star' },
  ...PLANETS.map(p=>({ name:p.name, color:p.color, meta:p.desc.split('·')[0].trim() })),
  { name:'Moon', color:0xb8b8b8, meta:'satellite' }
];
legendData.forEach(d=>{
  const li=document.createElement('li');
