    <span class="nm">${d.name}</span><span class="meta">${d.meta}</span>`;
  legendList.appendChild(li);
});

/* ============================================================
   INTERACTION — hover tooltip + raycast
   ============================================================ */
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
const tip = document.getElementById('tip');
const tipName = document.getElementById('tip-name');
const tipDesc = document.getElementById('tip-desc');
const tipDot = document.getElementById('tip-dot');
let hovered = null;

function onPointerMove(e){
  pointer.x = (e.clientX/window.innerWidth)*2 - 1;
  pointer.y = -(e.clientY/window.innerHeight)*2 + 1;
  raycaster.setFromCamera(pointer, camera);
  const hits = raycaster.intersectObjects(pickables, false);
  if(hits.length){
    const u = hits[0].object.userData;
    if(hovered !== u.name){
      hovered = u.name;
      tipName.textContent = u.name;
      tipDesc.textContent = u.desc;
      tipDot.style.background = '#'+u.color.toString(16).padStart(6,'0');
      tipDot.style.boxShadow = '0 0 8px #'+u.color.toString(16).padStart(6,'0');
      tip.classList.add('show');
      document.body.style.cursor='pointer';
    }
    tip.style.left = e.clientX+'px';
    tip.style.top = e.clientY+'px';
  } else {
    if(hovered){ hovered=null; tip.classList.remove('show'); document.body.style.cursor=''; }
  }
}
window.addEventListener('pointermove', onPointerMove);

/* ============================================================
   CONTROLS UI
   ============================================================ */
let timeScale = 1;
const speedInput = document.getElementById('speed');
const speedVal = document.getElementById('speed-val');
speedInput.addEventListener('input', ()=>{
  timeScale = parseFloat(speedInput.value);
  speedVal.textContent = timeScale.toFixed(1)+'×';
});

const btnOrbits = document.getElementById('btn-orbits');
const btnLabels = document.getElementById('btn-labels');
let showOrbits = true, showLabels = true;
btnOrbits.addEventListener('click', ()=>{
  showOrbits = !showOrbits;
  orbitLines.forEach(l=>l.visible=showOrbits);
  btnOrbits.classList.toggle('active', showOrbits);
});
btnLabels.addEventListener('click', ()=>{
  showLabels = !showLabels;
  labelSprites.forEach(l=>l.visible=showLabels);
  btnLabels.classList.toggle('active', showLabels);
});
document.getElementById('btn-reset').addEventListener('click', ()=>{
  camera.position.set(0,46,118);
  controls.target.set(0,0,0);
});

/* ============================================================
   ANIMATION LOOP
   ============================================================ */
const clock = new THREE.Clock();
let elapsed = 0;
const tTime = document.getElementById('t-time');
const tFov = document.getElementById('t-fov');

function animate(){
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  elapsed += dt * timeScale;

  // rotate planets + moons
  planetGroups.forEach(g=>{
    g.pivot.rotation.y += g.speed * dt * timeScale * 0.5;
    g.mesh.rotation.y += g.spin * dt * timeScale * 4;
    if(g.moonPivot) g.moonPivot.rotation.y += g.moonSpeed * dt * timeScale * 0.5;
  });

  // sun life
  sun.rotation.y += dt * 0.05;
  const pulse = 1 + Math.sin(elapsed*1.5)*0.04;
  corona.scale.set(34*pulse, 34*pulse, 1);
  halo.scale.set(16*(2-pulse), 16*(2-pulse), 1);
  sunLight.intensity = 3.2 + Math.sin(elapsed*2.2)*0.25;

  // starfield slow drift
  stars.rotation.y += dt * 0.004;

  controls.update();
  renderer.render(scene, camera);

  // telemetry
  tTime.textContent = elapsed.toFixed(1)+'s';
  tFov.textContent = Math.round(camera.fov)+'°';
}
animate();

/* ============================================================
   RESIZE
   ============================================================ */
window.addEventListener('resize', ()=>{
  camera.aspect = window.innerWidth/window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ============================================================
   EXPOSE + READY
   ============================================================ */
window.SCENE = scene;
window.CAMERA = camera;
window.RENDERER = renderer;

// reveal UI + hide loader
requestAnimationFrame(()=>{
  document.body.classList.add('ready');
  const loader = document.getElementById('loader');
  setTimeout(()=>loader.classList.add('hide'), 500);
});
</script>
</body>
</html>
