  #hud .row { font-size: 11px; letter-spacing: .12em; color: #9fb0c8; line-height: 1.75; }
  #hud .row b { color: #eaf1ff; font-weight: 600; }
  #hud .bar {
    width: 190px; height: 3px; background: rgba(255,255,255,.14);
    margin-top: 12px; border-radius: 2px; overflow: hidden;
  }
  #hud .bar i { display: block; height: 100%; width: 0%;
    background: linear-gradient(90deg, #ffb454, #ff7a3c); }
  #vignette {
    position: fixed; inset: 0; z-index: 5; pointer-events: none;
    background: radial-gradient(120% 120% at 50% 42%, transparent 55%, rgba(0,0,0,.45) 100%);
  }
</style>
</head>
<body>
<div id="app"></div>
<div id="vignette"></div>
<div id="hud">
  <div class="title">PROCEDURAL <span>CITY</span> BLOCK</div>
  <div class="row">BUILDINGS <b id="bcount">0</b> &nbsp;·&nbsp; GRID <b>7 × 7</b></div>
  <div class="row">MAIN STREET <b>→ +Z</b> &nbsp;·&nbsp; SUN <b>LOW</b></div>
  <div class="bar"><i id="prog"></i></div>
</div>

<script type="importmap">
{ "imports": { "three": "https://unpkg.com/three@0.160.0/build/three.module.js" } }
</script>

<script type="module">
import * as THREE from 'three';

/* ---------- deterministic RNG ---------- */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
const rand = mulberry32(20240517);
const rr = (a,b)=>a+rand()*(b-a);
const pick = a=>a[(rand()*a.length)|0];

/* ---------- renderer ---------- */
const renderer = new THREE.WebGLRenderer({ antialias:true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById('app').appendChild(renderer.domElement);

/* ---------- scene / fog / sky ---------- */
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x2a3550, 120, 560);

const sky = new THREE.Mesh(
  new THREE.SphereGeometry(1200, 32, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite:false, fog:false,
    uniforms:{ top:{value:new THREE.Color(0x0e1a33)}, mid:{value:new THREE.Color(0x3a4a72)}, bot:{value:new THREE.Color(0xff9a5c)} },
    vertexShader:`varying vec3 vP; void main(){ vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader:`varying vec3 vP; uniform vec3 top,mid,bot;
      void main(){ float h=normalize(vP).y; vec3 c=mix(bot,mid,smoothstep(-0.05,0.35,h)); c=mix(c,top,smoothstep(0.35,0.95,h)); gl_FragColor=vec4(c,1.0); }`
  })
);
scene.add(sky);

/* ---------- camera ---------- */
const camera = new THREE.PerspectiveCamera(58, innerWidth/innerHeight, 0.5, 2000);
camera.position.set(0, 12, -150);
camera.lookAt(0, 8, 0);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0x8ea6d6, 0x2a2018, 0.55));
scene.add(new THREE.AmbientLight(0x223047, 0.35));

const sun = new THREE.DirectionalLight(0xffd9a8, 2.4);
sun.position.set(-140, 120, -60);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 700;
const S = 260;
sun.shadow.camera.left = -S; sun.shadow.camera.right = S;
sun.shadow.camera.top = S;   sun.shadow.camera.bottom = -S;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.02;
scene.add(sun);
scene.add(sun.target);

/* ---------- ground ---------- */
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(1400, 1400),
  new THREE.MeshStandardMaterial({ color:0x14181f, roughness:1, metalness:0 })
);
ground.rotation.x = -Math.PI/2;
ground.receiveShadow = true;
scene.add(ground);

/* ---------- city grid ---------- */
const N = 7;                 // blocks per side
const BLOCK = 26;            // building footprint
const ROAD  = 14;            // road width
const PITCH = BLOCK + ROAD;  // 40
const HALF  = (N-1)*PITCH/2; // 120
const city = new THREE.Group();
scene.add(city);

const boxGeo = new THREE.BoxGeometry(1,1,1);
const winGeo = new THREE.PlaneGeometry(1,1);
const winMat = new THREE.MeshStandardMaterial({ color:0x0a0d14, emissive:0xffb454, emissiveIntensity:1.4, roughness:1, metalness:0 });
const winMatOff = new THREE.MeshStandardMaterial({ color:0x0a0d14, emissive:0x0a0d14, emissiveIntensity:0, roughness:1, metalness:0 });

const palette = [0x2b3140,0x333a49,0x3d4453,0x454c5c,0x2f3542,0x3a4150,0x4a5163,0x565d6e,0x262b36,0x40475a];
const litChance = 0.55;

let buildingCount = 0;

function addWindows(mesh, w, d, h, y0){
  const cols = Math.max(1, Math.floor(w/3.2));
  const rows = Math.max(1, Math.floor(h/3.4));
  const lit = rand() < litChance;
  const mat = lit ? winMat : winMatOff;
  const winW = Math.min(1.7, w/cols*0.5);
  const winH = Math.min(1.9, h/rows*0.5);
  const faces = [
    { n:[0,0,1],  off:[0,0, d/2+0.02], span:w },
    { n:[0,0,-1], off:[0,0,-d/2-0.02], span:w },
    { n:[1,0,0],  off:[ w/2+0.02,0,0], span:d },
    { n:[-1,0,0], off:[-w/2-0.02,0,0], span:d },
  ];
  for(const f of faces){
    const c = Math.max(1, Math.floor(f.span/3.2));
    for(let i=0;i<c;i++){
      const x = (i+0.5)/c - 0.5;
      for(let j=0;j<rows;j++){
        const y = y0 + (j+0.5)/rows * h;
        const m = new THREE.Mesh(winGeo, mat);
        m.scale.set(winW, winH, 1);
        if(f.n[0]!==0){ m.rotation.y = Math.PI/2; m.position.set(f.off[0], y, x*f.span); }
        else { m.position.set(x*f.span, y, f.off[2]); }
        city.add(m);
      }
    }
  }
}

function addBuilding(cx, cz){
  const w = rr(16, BLOCK-2);
  const d = rr(16, BLOCK-2);
  const h = rr(10, 92);
  const y0 = 0;
  const mat = new THREE.MeshStandardMaterial({ color:pick(palette), roughness:rr(0.7,0.95), metalness:rr(0,0.15) });
  const mesh = new THREE.Mesh(boxGeo, mat);
  mesh.scale.set(w, h, d);
  mesh.position.set(cx, y0 + h/2, cz);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  city.add(mesh);
  addWindows(mesh, w, d, h, y0);

  // rooftop detail
  if(rand() < 0.7){
    const rw = rr(2, w*0.4), rd = rr(2, d*0.4), rh = rr(2, 6);
    const rm = new THREE.Mesh(boxGeo, new THREE.MeshStandardMaterial({ color:0x1c212b, roughness:0.9 }));
    rm.scale.set(rw, rh, rd);
    rm.position.set(cx + rr(-w*0.2,w*0.2), y0 + h + rh/2, cz + rr(-d*0.2,d*0.2));
    rm.castShadow = true; rm.receiveShadow = true;
    city.add(rm);
  }
  if(rand() < 0.4){
    const ah = rr(6, 16);
    const am = new THREE.Mesh(boxGeo, new THREE.MeshStandardMaterial({ color:0x2a303c, roughness:0.8 }));
    am.scale.set(0.6, ah, 0.6);
    am.position.set(cx + rr(-w*0.3,w*0.3), y0 + h + ah/2, cz + rr(-d*0.3,d*0.3));
    am.castShadow = true;
    city.add(am);
  }
  buildingCount++;
}

for(let i=0;i<N;i++){
  for(let j=0;j<N;j++){
    const cx = -HALF + i*PITCH;
    const cz = -HALF + j*PITCH;
    addBuilding(cx, cz);
  }
}
document.getElementById('bcount').textContent = buildingCount;

/* ---------- road markings (emissive, no textures) ---------- */
const dashMat = new THREE.MeshStandardMaterial({ color:0x0a0a0a, emissive:0xffe9b0, emissiveIntensity:0.9, roughness:1 });
const dashGeo = new THREE.PlaneGeometry(0.5, 3);
const dashCount = 40;
const dashes = new THREE.InstancedMesh(dashGeo, dashMat, dashCount*2);
dashes.rotation.x = -Math.PI/2;
dashes.receiveShadow = true;
const m4 = new THREE.Matrix4();
let di = 0;
for(let k=0;k<dashCount;k++){
  const z = -HALF - 20 + k*8;
  m4.makeTranslation(0, 0.02, z); dashes.setMatrixAt(di++, m4);
  m4.makeTranslation(0, 0.02, z); dashes.setMatrixAt(di++, m4); // second lane offset below
}
// offset the second set to the other side of the main street
for(let k=0;k<dashCount;k++){
  const z = -HALF - 20 + k*8;
  m4.makeTranslation(ROAD*0.5, 0.02, z); dashes.setMatrixAt(dashCount + k, m4);
}
dashes.instanceMatrix.needsUpdate = true;
scene.add(dashes);

/* ---------- camera flight ---------- */
const clock = new THREE.Clock();
const prog = document.getElementById('prog');
const LOOP = 320; // travel length before wrap
let t = 0;

function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt;

  const speed = 14;
  const z = -150 + ((t*speed) % LOOP);
  const x = Math.sin(t*0.15) * 6;
  const y = 12 + Math.sin(t*0.4) * 1.5;
  camera.position.set(x, y, z);
  camera.lookAt(x*0.4, 8, z + 40);

  // keep sun shadow frustum tracking the camera
  sun.target.position.set(x, 0, z + 40);
  sun.position.set(x - 140, 120, z - 60);

  prog.style.width = (((t*speed) % LOOP) / LOOP * 100).toFixed(1) + '%';

  renderer.render(scene, camera);
}
animate();

/* ---------- expose for inspection ---------- */
window.SCENE = scene;
window.CAMERA = camera;
window.RENDERER = renderer;

/* ---------- resize ---------- */
addEventListener('resize', ()=>{
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
